            dividers.append(("v", c, grid[0][c]))

    def canon(cells):
        forms = []
        for flip in (1, -1):
            for rot in range(4):
                pts = []
                for y, x, v in cells:
                    x *= flip
                    for _ in range(rot):
                        y, x = x, -y
                    pts.append((y, x, v))
                my = min(y for y, x, v in pts)
                mx = min(x for y, x, v in pts)
                forms.append(tuple(sorted((y-my, x-mx, v) for y, x, v in pts)))
        return min(forms)

    def orientations(cells):
        found = set()
        result = []
        for flip in (1, -1):
            for rot in range(4):
                pts = []
                for y, x, v in cells:
                    x *= flip
                    for _ in range(rot):
                        y, x = x, -y
                    pts.append((y, x, v))
                my = min(y for y, x, v in pts)
                mx = min(x for y, x, v in pts)
                pts = tuple(sorted((y-my, x-mx, v) for y, x, v in pts))
                if pts not in found:
                    found.add(pts)
                    result.append(pts)
        return result

    for direction, k, line_color in dividers:
        if direction == "h":
            panels = [grid[:k], grid[k+1:]]
        else:
            panels = [[row[:k] for row in grid],
                      [row[k+1:] for row in grid]]
        if any(not p or not p[0] for p in panels):
            continue

        for ti in (0, 1):
            template, source = panels[ti], panels[1-ti]
            tc, sc = {}, {}
            for row in template:
                for x in row:
                    tc[x] = tc.get(x, 0) + 1
            for row in source:
                for x in row:
                    sc[x] = sc.get(x, 0) + 1
            if len(tc) != 2 or len(sc) <= 2:
                continue

            tbg = max(tc, key=tc.get)
            mask_color = next(x for x in tc if x != tbg)
            sbg = max(sc, key=sc.get)
            mask = {(r, c) for r in range(len(template))
                    for c in range(len(template[0]))
                    if template[r][c] == mask_color}
            if line_color != sbg or sum(v != sbg for row in source for v in row) != len(mask):
                continue

            # Extract the connected colored pieces from the source panel.
            sh, sw = len(source), len(source[0])
            seen = set()
            pieces = []
            for r in range(sh):
                for c in range(sw):
                    if source[r][c] == sbg or (r, c) in seen:
                        continue
                    stack = [(r, c)]
                    seen.add((r, c))
                    cells = []
                    while stack:
                        y, x = stack.pop()
                        cells.append((y, x, source[y][x]))
                        for yy, xx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                            if (0 <= yy < sh and 0 <= xx < sw and
                                    source[yy][xx] != sbg and (yy,xx) not in seen):
                                seen.add((yy,xx))
                                stack.append((yy,xx))
                    my = min(y for y,x,v in cells)
                    mx = min(x for y,x,v in cells)
                    pieces.append([(y-my, x-mx, v) for y,x,v in cells])

            if sum(map(len, pieces)) != len(mask):
                continue

            # Identical pieces are interchangeable; group them to avoid redundant search.
            signatures = [canon(p) for p in pieces]
            opts = []
            for p in pieces:
                placements = []
                for shape in orientations(p):
                    ph = max(y for y,x,v in shape) + 1
                    pw = max(x for y,x,v in shape) + 1
                    for dy in range(len(template)-ph+1):
                        for dx in range(len(template[0])-pw+1):
                            cells = {(dy+y, dx+x) for y,x,v in shape}
                            if cells <= mask:
                                placements.append((cells, [(dy+y,dx+x,v) for y,x,v in shape]))
                # Eliminate duplicated placement descriptions.
                unique = {}
                for pos, pixels in placements:
                    unique[tuple(sorted(pixels))] = (pos, pixels)
                opts.append(list(unique.values()))

            used = set()
            occupied = set()
            selected = []

            def search():
                if len(used) == len(pieces):
                    return occupied == mask

                best_options = None
                for cell in mask - occupied:
                    choices = []
                    for i in range(len(pieces)):
                        if i in used:
                            continue
                        # Skip equivalent unused pieces except the first one.
                        if any(j not in used and signatures[j] == signatures[i]
                               for j in range(i)):
                            continue
                        for pos, pixels in opts[i]:
                            if cell in pos and not (pos & occupied):
                                choices.append((i, pos, pixels))
                    if best_options is None or len(choices) < len(best_options):
                        best_options = choices
                        if not choices:
                            return False

                for i, pos, pixels in best_options:
                    used.add(i)
                    occupied.update(pos)
                    selected.append(pixels)
                    if search():
                        return True
                    selected.pop()
                    occupied.difference_update(pos)
                    used.remove(i)
                return False

            if search():
                out = [[tbg for _ in row] for row in template]
                for pixels in selected:
                    for r, c, v in pixels:
                        out[r][c] = v
                return out

    return grid
